window.ATLAS_PRIORITY_DETAILS=window.ATLAS_PRIORITY_DETAILS||{};window.ATLAS_PRIORITY_DETAILS["evidence-002"]={"ZMAT1":{"coreEvidence":[{"partner":"H2AX","hgnc":"HGNC:4739","core":true,"core_annotation":{"hgnc":"HGNC:4739","symbol_at_source":"H2AFX","accession":"P16104","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":507,"hub_weight":0.29961075885598987,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Variant histone H2A which replaces conventional H2A in a subset of nucleosomes. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling. Required for checkpoint-mediated arrest of cell cycle progression in response to low doses of ionizing radiation and for efficient repair of DNA double strand breaks (DSBs) specifically when modified by C-terminal phosphorylation","source":"project UniProt records20261017/18"},{"partner":"OIP5","hgnc":"HGNC:20300","core":true,"core_annotation":{"hgnc":"HGNC:20300","symbol_at_source":"OIP5","accession":"O43482","function":"Chromatin remodeling","target":"histone","pmids":["17199038"],"complexes":"Mis18","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":152,"hub_weight":0.4975185951049946,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Chromosome, centromere","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for recruitment of CENPA to centromeres and normal chromosome segregation during mitosis","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"FBXO48":{"coreEvidence":[{"partner":"SKP1","hgnc":"HGNC:10899","core":true,"core_annotation":{"hgnc":"HGNC:10899","symbol_at_source":"SKP1","accession":"P63208","function":"Histone modification write cofactor","target":"histone","pmids":["16943429"],"complexes":"BCOR","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":412,"hub_weight":0.3289758474798845,"quality":0.75,"programmes":["CCSB_binary_maps","pubmed:37831778"],"pmids":["32296183","37831778"],"assays":["binary_reporter","capture_association"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Essential component of the SCF (SKP1-CUL1-F-box protein) ubiquitin ligase complex, which mediates the ubiquitination of proteins involved in cell cycle progression, signal transduction and transcription. In the SCF complex, serves as an adapter that links the F-box protein to CUL1. The functional specificity of the SCF complex depends on the F-box protein as substrate recognition component. SCF(BTRC) and SCF(FBXW11) direct ubiquitination of CTNNB1 and participate in Wnt signaling. SCF(FBXW11) directs ubiquitination of phosphorylated NFKBIA. SCF(BTRC) directs ubiquitination of NFKBIB, NFKBIE, ATF4, SMAD3, SMAD4, CDC25A, FBXO5, CEP68 and probably NFKB2 (PubMed:25704143). SCF(SKP2) directs ubiquitination of phosphorylated CDKN1B/p27kip and is involved in regulation of G1/S transition. SCF(SKP2) directs ubiquitination of ORC1, CDT1, RBL2, ELF4, CDKN1A, RAG2, FOXO1A, and probably MYC and TAL1. SCF(FBXW7) directs ubiquitination of cyclin E, NOTCH1 released notch intracellular domain (NICD), and probably PSEN1. SCF(FBXW2) directs ubiquitination of GCM1. SCF(FBXO32) directs ubiquitination of MYOD1. SCF(FBXO7) directs ubiquitination of BIRC2 and DLGAP5. SCF(FBXO33) directs ubiquitination of YBX1. SCF(FBXO11) directs ubiquitination of BCL6 and DTL but does not seem to direct ubiquitination of TP53. SCF(BTRC) mediates the ubiquitination of NFKBIA at 'Lys-21' and 'Lys-22'; the degradation frees the associated NFKB1-RELA dimer to translocate into the nucleus and to activate transcription. SCF(CCNF) directs ubiquitination of CCP110. SCF(FBXL3) and SCF(FBXL21) direct ubiquitination of CRY1 and CRY2. SCF(FBXO9) directs ubiquitination of TTI1 and TELO2. SCF(FBXO10) directs ubiquitination of BCL2. Core component of the Cul7-RING(FBXW8) ubiquitin ligase complex, which mediates the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:35982156). Also acts as a core component of the Cul1-RING(FBXL4) ubiquitin ligase complex, which mediates the ubiquitination and subsequent proteasomal degradation of BNIP3 and BNI3L (PubMed:36896912)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"MAGIX":{"coreEvidence":[{"partner":"H2BC13","hgnc":"HGNC:4748","core":true,"core_annotation":{"hgnc":"HGNC:4748","symbol_at_source":"HIST1H2BL","accession":"Q99880","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":283,"hub_weight":0.3874921291460643,"quality":0.65,"programmes":["pubmed:30021884"],"pmids":["30021884"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"PBK","hgnc":"HGNC:18282","core":true,"core_annotation":{"hgnc":"HGNC:18282","symbol_at_source":"PBK","accession":"Q96KB5","function":"Histone modification write","target":"histone","pmids":["16982762"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":193,"hub_weight":0.45360921162651446,"quality":0.65,"programmes":["pubmed:36115835"],"pmids":["36115835"],"assays":["capture_association"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Phosphorylates MAP kinase p38. Seems to be active only in mitosis. May also play a role in the activation of lymphoid cells. When phosphorylated, forms a complex with TP53, leading to TP53 destabilization and attenuation of G2/M checkpoint during doxorubicin-induced DNA damage","source":"project UniProt records20261017/18"},{"partner":"H2BC18","hgnc":"HGNC:24700","core":true,"core_annotation":{"hgnc":"HGNC:24700","symbol_at_source":"HIST2H2BF","accession":"Q5QNW6","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":253,"hub_weight":0.40622223185119377,"quality":0.65,"programmes":["pubmed:30021884"],"pmids":["30021884"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"WDR25":{"coreEvidence":[{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:37788672"],"pmids":["37788672"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"EYA4","hgnc":"HGNC:3522","core":true,"core_annotation":{"hgnc":"HGNC:3522","symbol_at_source":"EYA4","accession":"O95677","function":"Histone modification erase","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":212,"hub_weight":0.436852028330519,"quality":0.4,"programmes":["pubmed:38360978"],"pmids":["38360978"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Tyrosine phosphatase that specifically dephosphorylates 'Tyr-142' of histone H2AX (H2AXY142ph). 'Tyr-142' phosphorylation of histone H2AX plays a central role in DNA repair and acts as a mark that distinguishes between apoptotic and repair responses to genotoxic stress. Promotes efficient DNA repair by dephosphorylating H2AX, promoting the recruitment of DNA repair complexes containing MDC1. Its function as histone phosphatase probably explains its role in transcription regulation during organogenesis. May be involved in development of the eye (By similarity)","source":"project UniProt records20261017/18"},{"partner":"PRDM14","hgnc":"HGNC:14001","core":true,"core_annotation":{"hgnc":"HGNC:14001","symbol_at_source":"PRDM14","accession":"Q9GZV8","function":"DNA modification","target":"DNA","pmids":["24335252"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":73,"hub_weight":0.6375767130633383,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcription factor that has both positive and negative roles on transcription. Required for the maintenance of embryonic stem cell identity and the reacquisition of pluripotency in somatic cells. May play an essential role in germ cell development at 2 levels: the reacquisition of potential pluripotency, including SOX2 up-regulation, and successful epigenetic reprogramming, characterized by EHMT1 repression. Its association with CBFA2T2 is required for the functions in pluripotency and germ cell formation (By similarity). Directly up-regulates the expression of pluripotency gene POU5F1 through its proximal enhancer. Binds to the DNA consensus sequence 5'-GGTC[TC]CTAA-3'","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PRELID2":{"coreEvidence":[{"partner":"BRCA2","hgnc":"HGNC:1101","core":true,"core_annotation":{"hgnc":"HGNC:1101","symbol_at_source":"BRCA2","accession":"P51587","function":"Histone modification write","target":"histone, DNA","pmids":["9619837"],"complexes":"BRCC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":185,"hub_weight":0.46126560401444255,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Chromosome; Chromosome, telomere; Nucleus; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Tumor suppressor protein that maintains genome stability primarily by repairing damaged DNA through homologous recombination (HR) (PubMed:11239456, PubMed:12442171, PubMed:15115758, PubMed:15199141, PubMed:15671039, PubMed:15937124, PubMed:17515903, PubMed:17515904, PubMed:18317453, PubMed:19303847, PubMed:20729832, PubMed:20729858, PubMed:20729859, PubMed:21719596, PubMed:27941124, PubMed:37499663, PubMed:37515771). Facilitates the repair of double-strand breaks (DSBs) by binding and mediating the loading of the RAD51 protein onto single-stranded DNA (ssDNA), thereby promoting the activity of RAD51, which catalyzes DNA strand exchange (PubMed:11239456, PubMed:12442171, PubMed:15937124, PubMed:17515903, PubMed:17515904, PubMed:18317453, PubMed:19303847, PubMed:20729832, PubMed:20729858, PubMed:20729859, PubMed:27941124, PubMed:37499663). BRCA2 nucleates and stabilizes RAD51 on ssDNA directly and delivers RAD51 to ssDNA-double-stranded DNA (dsDNA) junctions by sliding along dsDNA backbone (PubMed:12442171, PubMed:19303847, PubMed:37499663). RAD51 targeting to ssDNA promotes removal of replication protein-A (RPA) from ssDNA and stabilization of RAD51-ssDNA filaments by blocking ATP hydrolysis (PubMed:20729859). May play a role in the extension step after strand invasion at replication-dependent DNA double-strand breaks; together with PALB2 is involved in both POLH localization at collapsed replication forks and DNA polymerization activity (PubMed:24485656). Required to prevent R-loop-associated DNA damage and thus transcription-associated genomic instability (PubMed:24896180). Silencing of BRCA2 promotes R-loop accumulation at actively transcribed genes in replicating and non-replicating cells, suggesting that BRCA2 mediates the control of R-loop associated genomic instability, independently of its known role in homologous recombination (PubMed:24896180). Also promotes RAD51 loading to telomeric regions, facilitating telomere replication and capping (PubMed:21076401). Also required for homologous recombination during meiosis by promoting the recruitment of RAD51 and DMC1 recombinases to meiotic DSB sites, enabling proper chromosome pairing and crossing over (PubMed:26976601). Also promotes homologous recombination by inactivating the FIGNL1-FIRRM complex to protect RAD51 filament from premature disassembly (PubMed:37515771). Together with NPM1, may also regulate centrosome duplication (PubMed:21084279)","source":"project UniProt records20261017/18"},{"partner":"BUB1","hgnc":"HGNC:1148","core":true,"core_annotation":{"hgnc":"HGNC:1148","symbol_at_source":"BUB1","accession":"O43683","function":"Histone modification write","target":"histone","pmids":["20929775"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":105,"hub_weight":0.5679618342470648,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome, centromere, kinetochore","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine-protein kinase that performs 2 crucial functions during mitosis: it is essential for spindle-assembly checkpoint signaling and for correct chromosome alignment. Has a key role in the assembly of checkpoint proteins at the kinetochore, being required for the subsequent localization of CENPF, BUB1B, CENPE and MAD2L1. Required for the kinetochore localization of PLK1. Required for centromeric enrichment of AUKRB in prometaphase. Plays an important role in defining SGO1 localization and thereby affects sister chromatid cohesion. Promotes the centromeric localization of TOP2A (PubMed:35044816). Acts as a substrate for anaphase-promoting complex or cyclosome (APC/C) in complex with its activator CDH1 (APC/C-Cdh1). Necessary for ensuring proper chromosome segregation and binding to BUB3 is essential for this function. Can regulate chromosome segregation in a kinetochore-independent manner. Can phosphorylate BUB3. The BUB1-BUB3 complex plays a role in the inhibition of APC/C when spindle-assembly checkpoint is activated and inhibits the ubiquitin ligase activity of APC/C by phosphorylating its activator CDC20. This complex can also phosphorylate MAD1L1. Kinase activity is essential for inhibition of APC/CCDC20 and for chromosome alignment but does not play a major role in the spindle-assembly checkpoint activity. Mediates cell death in response to chromosome missegregation and acts to suppress spontaneous tumorigenesis","source":"project UniProt records20261017/18"},{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:37788672"],"pmids":["37788672"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"FAM135A":{"coreEvidence":[{"partner":"CLNS1A","hgnc":"HGNC:2080","core":true,"core_annotation":{"hgnc":"HGNC:2080","symbol_at_source":"CLNS1A","accession":"P54105","function":"Histone modification write cofactor","target":"#","pmids":[],"complexes":"methylosome","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":150,"hub_weight":0.5,"quality":0.65,"programmes":["pubmed:35271311"],"pmids":["35271311"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm, cytosol; Nucleus; Cytoplasm, cytoskeleton","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in both the assembly of spliceosomal snRNPs and the methylation of Sm proteins (PubMed:10330151, PubMed:11713266, PubMed:18984161, PubMed:21081503). Chaperone that regulates the assembly of spliceosomal U1, U2, U4 and U5 small nuclear ribonucleoproteins (snRNPs), the building blocks of the spliceosome, and thereby plays an important role in the splicing of cellular pre-mRNAs (PubMed:10330151, PubMed:18984161). Most spliceosomal snRNPs contain a common set of Sm proteins SNRPB, SNRPD1, SNRPD2, SNRPD3, SNRPE, SNRPF and SNRPG that assemble in a heptameric protein ring on the Sm site of the small nuclear RNA to form the core snRNP (Sm core) (PubMed:10330151). In the cytosol, the Sm proteins SNRPD1, SNRPD2, SNRPE, SNRPF and SNRPG are trapped in an inactive 6S pICln-Sm complex by the chaperone CLNS1A that controls the assembly of the core snRNP (PubMed:10330151, PubMed:18984161). Dissociation by the SMN complex of CLNS1A from the trapped Sm proteins and their transfer to an SMN-Sm complex triggers the assembly of core snRNPs and their transport to the nucleus (PubMed:10330151, PubMed:18984161)","source":"project UniProt records20261017/18"},{"partner":"HIF1AN","hgnc":"HGNC:17113","core":true,"core_annotation":{"hgnc":"HGNC:17113","symbol_at_source":"HIF1AN","accession":"Q9NWT6","function":"Histone modification erase cofactor","target":"histone","pmids":["11641274"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":241,"hub_weight":0.41451333614483915,"quality":0.65,"programmes":["pubmed:26972000"],"pmids":["26972000"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Cytoplasm, perinuclear region","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Hydroxylates HIF-1 alpha at 'Asn-803' in the C-terminal transactivation domain (CAD). Functions as an oxygen sensor and, under normoxic conditions, the hydroxylation prevents interaction of HIF-1 with transcriptional coactivators including Cbp/p300-interacting transactivator. Involved in transcriptional repression through interaction with HIF1A, VHL and histone deacetylases. Hydroxylates specific Asn residues within ankyrin repeat domains (ARD) of NFKB1, NFKBIA, NOTCH1, ASB4, PPP1R12A and several other ARD-containing proteins. Also hydroxylates Asp and His residues within ARDs of ANK1 and TNKS2, respectively. Negatively regulates NOTCH1 activity, accelerating myogenic differentiation. Positively regulates ASB4 activity, promoting vascular differentiation","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"KLHL38":{"coreEvidence":[{"partner":"TADA2A","hgnc":"HGNC:11531","core":true,"core_annotation":{"hgnc":"HGNC:11531","symbol_at_source":"TADA2A","accession":"O75478","function":"Histone modification read, TF","target":"histone","pmids":["19103755"],"complexes":"PCAF, ATAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":182,"hub_weight":0.46423834544262965,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["25416956"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the ATAC complex, a complex with histone acetyltransferase activity on histones H3 and H4. Required for the function of some acidic activation domains, which activate transcription from a distant site (By similarity). Binds double-stranded DNA. Binds dinucleosomes, probably at the linker region between neighboring nucleosomes. Plays a role in chromatin remodeling. May promote TP53/p53 'Lys-321' acetylation, leading to reduced TP53 stability and transcriptional activity (PubMed:22644376). May also promote XRCC6 acetylation thus facilitating cell apoptosis in response to DNA damage (PubMed:22644376)","source":"project UniProt records20261017/18"},{"partner":"OIP5","hgnc":"HGNC:20300","core":true,"core_annotation":{"hgnc":"HGNC:20300","symbol_at_source":"OIP5","accession":"O43482","function":"Chromatin remodeling","target":"histone","pmids":["17199038"],"complexes":"Mis18","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":152,"hub_weight":0.4975185951049946,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Chromosome, centromere","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for recruitment of CENPA to centromeres and normal chromosome segregation during mitosis","source":"project UniProt records20261017/18"},{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"XNDC1N":{"coreEvidence":[{"partner":"PARP3","hgnc":"HGNC:273","core":true,"core_annotation":{"hgnc":"HGNC:273","symbol_at_source":"PARP3","accession":"Q9Y6F1","function":"Polycomb group (PcG) protein","target":"#","pmids":["16924674"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":209,"hub_weight":0.4393747751637468,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Mono-ADP-ribosyltransferase that mediates mono-ADP-ribosylation of target proteins and plays a key role in the response to DNA damage (PubMed:16924674, PubMed:19354255, PubMed:20064938, PubMed:21211721, PubMed:21270334, PubMed:23742272, PubMed:24598253, PubMed:25043379, PubMed:28447610). Mediates mono-ADP-ribosylation of glutamate, aspartate or lysine residues on target proteins (PubMed:20064938, PubMed:25043379). In contrast to PARP1 and PARP2, it is not able to mediate poly-ADP-ribosylation (PubMed:25043379). Involved in DNA repair by mediating mono-ADP-ribosylation of a limited number of acceptor proteins involved in chromatin architecture and in DNA metabolism, such as histone H2B, XRCC5 and XRCC6 (PubMed:16924674, PubMed:24598253). ADP-ribosylation follows DNA damage and appears as an obligatory step in a detection/signaling pathway leading to the reparation of DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Involved in single-strand break repair by catalyzing mono-ADP-ribosylation of histone H2B on 'Glu-2' (H2BE2ADPr) of nucleosomes containing nicked DNA (PubMed:27530147). Cooperates with the XRCC5-XRCC6 (Ku80-Ku70) heterodimer to limit end-resection thereby promoting accurate NHEJ (PubMed:24598253). Suppresses G-quadruplex (G4) structures in response to DNA damage (PubMed:28447610). Associates with a number of DNA repair factors and is involved in the response to exogenous and endogenous DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Together with APLF, promotes the retention of the LIG4-XRCC4 complex on chromatin and accelerate DNA ligation during non-homologous end-joining (NHEJ) (PubMed:21211721). May link the DNA damage surveillance network to the mitotic fidelity checkpoint (PubMed:16924674). Acts as a negative regulator of immunoglobulin class switch recombination, probably by controlling the level of AICDA /AID on the chromatin (By similarity). In addition to proteins, also able to ADP-ribosylate DNA: mediates DNA mono-ADP-ribosylation of DNA strand break termini via covalent addition of a single ADP-ribose moiety to a 5'- or 3'-terminal phosphate residues in DNA containing multiple strand breaks (PubMed:29361132, PubMed:29520010)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"R3HDM4":{"coreEvidence":[{"partner":"H2BC9","hgnc":"HGNC:4755","core":true,"core_annotation":{"hgnc":"HGNC:4755","symbol_at_source":"HIST1H2BH","accession":"Q93079","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":327,"hub_weight":0.3641785203646149,"quality":0.65,"programmes":["pubmed:30021884"],"pmids":["30021884"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"NPM1","hgnc":"HGNC:7910","core":true,"core_annotation":{"hgnc":"HGNC:7910","symbol_at_source":"NPM1","accession":"P06748","function":"Histone chaperone","target":"histone","pmids":["25349213"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1053,"hub_weight":0.21291058142914557,"quality":0.65,"programmes":["pubmed:30021884"],"pmids":["30021884"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus, nucleolus; Nucleus, nucleoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in diverse cellular processes such as ribosome biogenesis, centrosome duplication, protein chaperoning, histone assembly, cell proliferation, and regulation of tumor suppressors p53/TP53 and ARF. Binds ribosome presumably to drive ribosome nuclear export. Associated with nucleolar ribonucleoprotein structures and bind single-stranded nucleic acids. Acts as a chaperonin for the core histones H3, H2B and H4. Stimulates APEX1 endonuclease activity on apurinic/apyrimidinic (AP) double-stranded DNA but inhibits APEX1 endonuclease activity on AP single-stranded RNA. May exert a control of APEX1 endonuclease activity within nucleoli devoted to repair AP on rDNA and the removal of oxidized rRNA molecules. In concert with BRCA2, regulates centrosome duplication. Regulates centriole duplication: phosphorylation by PLK2 is able to trigger centriole replication. Negatively regulates the activation of EIF2AK2/PKR and suppresses apoptosis through inhibition of EIF2AK2/PKR autophosphorylation. Antagonizes the inhibitory effect of ATF5 on cell proliferation and relieves ATF5-induced G2/M blockade (PubMed:22528486). In complex with MYC enhances the transcription of MYC target genes (PubMed:25956029). May act as chaperonin or cotransporter in the nucleolar localization of transcription termination factor TTF1 (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"OGFOD2":{"coreEvidence":[{"partner":"KAT5","hgnc":"HGNC:5275","core":true,"core_annotation":{"hgnc":"HGNC:5275","symbol_at_source":"KAT5","accession":"Q92993","function":"Histone modification write","target":"histone","pmids":["10096020"],"complexes":"SWR, NuA4, Piccolo_NuA4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":337,"hub_weight":0.3594425773447947,"quality":0.75,"programmes":["pubmed:16169070"],"pmids":["16169070"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm; Chromosome, centromere, kinetochore; Cytoplasm, cytoskeleton, spindle pole; Nucleus, nucleolus; Cytoplasm, perinuclear region; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of the NuA4 histone acetyltransferase complex, a multiprotein complex involved in transcriptional activation of select genes principally by acetylation of nucleosomal histones H2A and H4 (PubMed:12776177, PubMed:14966270, PubMed:15042092, PubMed:15121871, PubMed:15310756, PubMed:16387653, PubMed:19909775, PubMed:25865756, PubMed:27153538, PubMed:29174981, PubMed:29335245, PubMed:32822602, PubMed:33076429). Histone acetylation alters nucleosome-DNA interactions and promotes interaction of the modified histones with other proteins which positively regulate transcription (PubMed:12776177, PubMed:14966270, PubMed:15042092, PubMed:15121871, PubMed:15310756). The NuA4 histone acetyltransferase complex is required for the activation of transcriptional programs associated with proto-oncogene mediated growth induction, tumor suppressor mediated growth arrest and replicative senescence, apoptosis, and DNA repair (PubMed:17709392, PubMed:19783983, PubMed:32832608). The NuA4 complex plays a direct role in repair of DNA double-strand breaks (DSBs) by promoting homologous recombination (HR): the complex inhibits TP53BP1 binding to chromatin via MBTD1, which recognizes and binds histone H4 trimethylated at 'Lys-20' (H4K20me), and KAT5 that catalyzes acetylation of 'Lys-15' of histone H2A (H2AK15ac), thereby blocking the ubiquitination mark required for TP53BP1 localization at DNA breaks (PubMed:27153538, PubMed:32832608). Also involved in DSB repair by mediating acetylation of 'Lys-5' of histone H2AX (H2AXK5ac), promoting NBN/NBS1 assembly at the sites of DNA damage (PubMed:17709392, PubMed:26438602). The NuA4 complex plays a key role in hematopoietic stem cell maintenance and is required to maintain acetylated H2A.Z/H2AZ1 at MYC target genes (By similarity). The NuA4 complex is also required for spermatid development by promoting acetylation of histones: histone hyperacetylation is required for histone replacement during the transition from round to elongating spermatids (By similarity). Component of a SWR1-like complex that specifically mediates the removal of histone H2A.Z/H2AZ1 from the nucleosome (PubMed:24463511). Also acetylates non-histone proteins, such as BMAL1, ATM, AURKB, CHKA, CGAS, ERCC4/XPF, LPIN1, TP53/p53, NDC80/HEC1, NR1D2, RAN, SOX4, FOXP3, SQSTM1, ULK1 and RUBCNL/Pacer (PubMed:16141325, PubMed:17189187, PubMed:17360565, PubMed:17996965, PubMed:24835996, PubMed:26829474, PubMed:29040603, PubMed:30409912, PubMed:30704899, PubMed:31857589, PubMed:32034146, PubMed:32817552, PubMed:34077757). Directly acetylates and activates ATM (PubMed:16141325). Promotes nucleotide excision repair (NER) by mediating acetylation of ERCC4/XPF, thereby promoting formation of the ERCC4-ERCC1 complex (PubMed:32034146). Relieves NR1D2-mediated inhibition of APOC3 expression by acetylating NR1D2 (PubMed:17996965). Acts as a regulator of regulatory T-cells (Treg) by catalyzing FOXP3 acetylation, thereby promoting FOXP3 transcriptional repressor activity (PubMed:17360565, PubMed:24835996). Involved in skeletal myoblast differentiation by mediating acetylation of SOX4 (PubMed:26291311). Catalyzes acetylation of APBB1/FE65, increasing its transcription activator activity (PubMed:33938178). Promotes transcription elongation during the activation phase of the circadian cycle by catalyzing acetylation of BMAL1, promoting elongation of circadian transcripts (By similarity). Together with GSK3 (GSK3A or GSK3B), acts as a regulator of autophagy: phosphorylated at Ser-86 by GSK3 under starvation conditions, leading to activate acetyltransferase activity and promote acetylation of key autophagy regulators, such as ULK1 and RUBCNL/Pacer (PubMed:30704899). Acts as a regulator of the cGAS-STING innate antiviral response by catalyzing acetylation the N-terminus of CGAS, thereby promoting CGAS DNA-binding and activation (PubMed:32817552). Also regulates lipid metabolism by mediating acetylation of CHKA or LPIN1 (PubMed:34077757). Promotes lipolysis of lipid droplets following glucose deprivation by mediating acetylation of isoform 1 of CHKA, thereby promoting monomerization of CHKA and its conversion into a tyrosine-protein kinase (PubMed:34077757). Acts as a regulator of fatty-acid-induced triacylglycerol synthesis by catalyzing acetylation of LPIN1, thereby promoting the synthesis of diacylglycerol (PubMed:29765047). In addition to protein acetyltransferase, can use different acyl-CoA substrates, such as (2E)-butenoyl-CoA (crotonyl-CoA), S-lactoyl-CoA (lactyl-CoA) and 2-hydroxyisobutanoyl-CoA (2-hydroxyisobutyryl-CoA), and is able to mediate protein crotonylation, lactylation and 2-hydroxyisobutyrylation, respectively (PubMed:29192674, PubMed:34608293, PubMed:38961290). Acts as a key regulator of chromosome segregation and kinetochore-microtubule attachment during mitosis by mediating acetylation or crotonylation of target proteins (PubMed:26829474, PubMed:29040603, PubMed:30409912, PubMed:34608293). Catalyzes acetylation of AURKB at kinetochores, increasing AURKB activity and promoting accurate chromosome segregation in mitosis (PubMed:26829474). Acetylates RAN during mitosis, promoting microtubule assembly at mitotic chromosomes (PubMed:29040603). Acetylates NDC80/HEC1 during mitosis, promoting robust kinetochore-microtubule attachment (PubMed:30409912). Catalyzes crotonylation of MAPRE1/EB1, thereby ensuring accurate spindle positioning in mitosis (PubMed:34608293). Catalyzes lactylation of NBN/NBS1 in response to DNA damage, thereby promoting DNA double-strand breaks (DSBs) via homologous recombination (HR) (PubMed:38961290)\n(Microbial infection) Catalyzes the acetylation of flavivirus NS3 protein to modulate their RNA-binding and -unwinding activities leading to facilitate viral replication","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"MTMR10":{"coreEvidence":[{"partner":"PARP1","hgnc":"HGNC:270","core":true,"core_annotation":{"hgnc":"HGNC:270","symbol_at_source":"PARP1","accession":"P09874","function":"Chromatin remodeling","target":"histone","pmids":["20926656","17177976","17396150"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1585,"hub_weight":0.17487435419566724,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Chromosome; Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:17177976, PubMed:18055453, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:20388712, PubMed:21680843, PubMed:22582261, PubMed:23230272, PubMed:25043379, PubMed:26344098, PubMed:26626479, PubMed:26626480, PubMed:30104678, PubMed:31796734, PubMed:32028527, PubMed:32241924, PubMed:32358582, PubMed:33186521, PubMed:34465625, PubMed:34737271). Mediates glutamate, aspartate, serine, histidine or tyrosine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:19764761, PubMed:25043379, PubMed:28190768, PubMed:29954836, PubMed:35393539, PubMed:7852410, PubMed:9315851). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:33186521, PubMed:34874266, PubMed:41062835). Specificity for the different amino acids is conferred by interacting factors, such as HPF1 and NMNAT1 (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 confers serine specificity by completing the PARP1 active site (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Also catalyzes tyrosine ADP-ribosylation of target proteins following interaction with HPF1 (PubMed:29954836, PubMed:30257210). Following interaction with NMNAT1, catalyzes glutamate and aspartate ADP-ribosylation of target proteins; NMNAT1 confers glutamate and aspartate specificity (By similarity). PARP1 initiates the repair of DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones (H2BS6ADPr and H3S10ADPr), thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:17177976, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:23230272, PubMed:27067600, PubMed:34465625, PubMed:34874266). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP1 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). In addition to base excision repair (BER) pathway, also involved in double-strand breaks (DSBs) repair: together with TIMELESS, accumulates at DNA damage sites and promotes homologous recombination repair by mediating poly-ADP-ribosylation (PubMed:26344098, PubMed:30356214). Mediates the poly-ADP-ribosylation of a number of proteins, including itself, APLF, CHFR, RPA1 and NFAT5 (PubMed:17396150, PubMed:19764761, PubMed:24906880, PubMed:34049076). In addition to proteins, also able to ADP-ribosylate DNA: catalyzes ADP-ribosylation of DNA strand break termini containing terminal phosphates and a 2'-OH group in single- and double-stranded DNA, respectively (PubMed:27471034). Required for PARP9 and DTX3L recruitment to DNA damage sites (PubMed:23230272). PARP1-dependent PARP9-DTX3L-mediated ubiquitination promotes the rapid and specific recruitment of 53BP1/TP53BP1, UIMC1/RAP80, and BRCA1 to DNA damage sites (PubMed:23230272). PARP1-mediated DNA repair in neurons plays a role in sleep: senses DNA damage in neurons and promotes sleep, facilitating efficient DNA repair (By similarity). In addition to DNA repair, also involved in other processes, such as transcription regulation, programmed cell death, membrane repair, adipogenesis and innate immunity (PubMed:15607977, PubMed:17177976, PubMed:19344625, PubMed:27256882, PubMed:32315358, PubMed:32844745, PubMed:35124853, PubMed:35393539, PubMed:35460603). Acts as a repressor of transcription: binds to nucleosomes and modulates chromatin structure in a manner similar to histone H1, thereby altering RNA polymerase II (PubMed:15607977, PubMed:22464733). Acts both as a positive and negative regulator of transcription elongation, depending on the context (PubMed:27256882, PubMed:35393539). Acts as a positive regulator of transcription elongation by mediating poly-ADP-ribosylation of NELFE, preventing RNA-binding activity of NELFE and relieving transcription pausing (PubMed:27256882). Acts as a negative regulator of transcription elongation in response to DNA damage by catalyzing poly-ADP-ribosylation of CCNT1, disrupting the phase separation activity of CCNT1 and subsequent activation of CDK9 (PubMed:35393539). Involved in replication fork progression following interaction with CARM1: mediates poly-ADP-ribosylation at replication forks, slowing fork progression (PubMed:33412112). Poly-ADP-ribose chains generated by PARP1 also play a role in poly-ADP-ribose-dependent cell death, a process named parthanatos (By similarity). Also acts as a negative regulator of the cGAS-STING pathway (PubMed:32315358, PubMed:32844745, PubMed:35460603). Acts by mediating poly-ADP-ribosylation of CGAS: PARP1 translocates into the cytosol following phosphorylation by PRKDC and catalyzes poly-ADP-ribosylation and inactivation of CGAS (PubMed:35460603). Acts as a negative regulator of adipogenesis: catalyzes poly-ADP-ribosylation of histone H2B on 'Glu-35' (H2BE35ADPr) following interaction with NMNAT1, inhibiting phosphorylation of H2B at 'Ser-36' (H2BS36ph), thereby blocking expression of pro-adipogenetic genes (By similarity). Involved in the synthesis of ATP in the nucleus, together with NMNAT1, PARG and NUDT5 (PubMed:27257257). Nuclear ATP generation is required for extensive chromatin remodeling events that are energy-consuming (PubMed:27257257). Plays a role in sister chromatid cohesion by mediating ADP-ribosylation of RSMC during S phase which promotes the interaction between RSMC and CDCA5/sororin, leading to enhanced interaction of CDCA5/sororin with the cohesin complex and promotion of sister chromatid cohesion (PubMed:41261216)\nPromotes AIFM1-mediated apoptosis (PubMed:33168626). This form, which translocates into the cytoplasm following cleavage by caspase-3 (CASP3) and caspase-7 (CASP7) in response to apoptosis, is auto-poly-ADP-ribosylated and serves as a poly-ADP-ribose carrier to induce AIFM1-mediated apoptosis (PubMed:33168626)\nThis cleavage form irreversibly binds to DNA breaks and interferes with DNA repair, promoting DNA damage-induced apoptosis","source":"project UniProt records20261017/18"},{"partner":"YWHAZ","hgnc":"HGNC:12855","core":true,"core_annotation":{"hgnc":"HGNC:12855","symbol_at_source":"YWHAZ","accession":"P63104","function":"Histone modification read","target":"histone","pmids":["16246723"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":960,"hub_weight":0.2224970797449924,"quality":0.65,"programmes":["pubmed:35271311"],"pmids":["35271311"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm; Melanosome","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways (PubMed:14578935, PubMed:15071501, PubMed:15644438, PubMed:16376338, PubMed:16959763, PubMed:31024343, PubMed:9360956). Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif (PubMed:35662396). Binding generally results in the modulation of the activity of the binding partner (PubMed:35662396). Promotes cytosolic retention and inactivation of TFEB transcription factor by binding to phosphorylated TFEB (PubMed:35662396). Induces ARHGEF7 activity on RAC1 as well as lamellipodia and membrane ruffle formation (PubMed:16959763). In neurons, regulates spine maturation through the modulation of ARHGEF7 activity (By similarity)","source":"project UniProt records20261017/18"},{"partner":"PBRM1","hgnc":"HGNC:30064","core":true,"core_annotation":{"hgnc":"HGNC:30064","symbol_at_source":"PBRM1","accession":"Q86U86","function":"Histone modification read","target":"histone","pmids":["22464331"],"complexes":"PBAF, SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":213,"hub_weight":0.4360207201969473,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Required for the stability of the SWI/SNF chromatin remodeling complex SWI/SNF-B (PBAF). Acts as a negative regulator of cell proliferation","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"C21orf58":{"coreEvidence":[{"partner":"ASH2L","hgnc":"HGNC:744","core":true,"core_annotation":{"hgnc":"HGNC:744","symbol_at_source":"ASH2L","accession":"Q9UBL3","function":"Histone modification write cofactor","target":"histone","pmids":["21285357"],"complexes":"COMPASS, Menin-associated_HMT, MLL-HCF, CHD8, MLL2/3, COMPASS-like MLL1,2, MLL4/WBP7, COMPASS-like MLL3,4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":240,"hub_weight":0.41522739926869984,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional regulator (PubMed:12670868). Component or associated component of some histone methyltransferase complexes which regulates transcription through recruitment of those complexes to gene promoters (PubMed:19131338). Component of the Set1/Ash2 histone methyltransferase (HMT) complex, a complex that specifically methylates 'Lys-4' of histone H3, but not if the neighboring 'Lys-9' residue is already methylated (PubMed:19556245). As part of the MLL1/MLL complex it is involved in methylation and dimethylation at 'Lys-4' of histone H3 (PubMed:19556245). May play a role in hematopoiesis (PubMed:12670868). In association with RBBP5 and WDR5, stimulates the histone methyltransferase activities of KMT2A, KMT2B, KMT2C, KMT2D, SETD1A and SETD1B (PubMed:21220120, PubMed:22266653)","source":"project UniProt records20261017/18"},{"partner":"MTA2","hgnc":"HGNC:7411","core":true,"core_annotation":{"hgnc":"HGNC:7411","symbol_at_source":"MTA2","accession":"O94776","function":"Histone modification erase cofactor","target":"histone","pmids":["10444591"],"complexes":"NuRD","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":427,"hub_weight":0.32376195411908804,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May function as a transcriptional coregulator (PubMed:16428440, PubMed:28977666). Acts as a component of the histone deacetylase NuRD complex which participates in the remodeling of chromatin (PubMed:16428440, PubMed:28977666)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"SUSD1":{"coreEvidence":[{"partner":"ATF7IP","hgnc":"HGNC:20092","core":true,"core_annotation":{"hgnc":"HGNC:20092","symbol_at_source":"ATF7IP","accession":"Q6VMQ6","function":"Histone modification write cofactor","target":"histone","pmids":["14536086"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":95,"hub_weight":0.5872202195147035,"quality":0.75,"programmes":["pubmed:15231748"],"pmids":["15231748"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Recruiter that couples transcriptional factors to general transcription apparatus and thereby modulates transcription regulation and chromatin formation. Can both act as an activator or a repressor depending on the context. Required for HUSH-mediated heterochromatin formation and gene silencing (PubMed:27732843). Mediates MBD1-dependent transcriptional repression, probably by recruiting complexes containing SETDB1 (PubMed:12665582). Stabilizes SETDB1, is required to stimulate histone methyltransferase activity of SETDB1 and facilitates the conversion of dimethylated to trimethylated H3 'Lys-9' (H3K9me3). The complex formed with MBD1 and SETDB1 represses transcription and couples DNA methylation and histone H3 'Lys-9' trimethylation (H3K9me3) (PubMed:14536086, PubMed:27732843). Facilitates telomerase TERT and TERC gene expression by SP1 in cancer cells (PubMed:19106100)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"LENG9":{"coreEvidence":[{"partner":"OGT","hgnc":"HGNC:8127","core":true,"core_annotation":{"hgnc":"HGNC:8127","symbol_at_source":"OGT","accession":"O15294","function":"Histone modification write","target":"histone","pmids":["22121020"],"complexes":"NSL","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":741,"hub_weight":0.2514182275771345,"quality":1,"programmes":["pubmed:32994395"],"pmids":["32994395"],"assays":["reconstituted"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Mitochondrion; Membrane; Cytoplasm; Nucleus; Cell membrane; Mitochondrion membrane; Cell projection; Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalyzes the transfer of a single N-acetylglucosamine from UDP-GlcNAc to a serine or threonine residue in cytoplasmic and nuclear proteins resulting in their modification with a beta-linked N-acetylglucosamine (O-GlcNAc) (PubMed:12150998, PubMed:15361863, PubMed:19451179, PubMed:20018868, PubMed:21240259, PubMed:21285374, PubMed:23103939, PubMed:26237509, PubMed:26369908, PubMed:26678539, PubMed:27713473, PubMed:37541260, PubMed:37962578). Glycosylates a large and diverse number of proteins including histone H2B, AKT1, AMPK, ATG4B, CAPRIN1, EZH2, FNIP1, GSDMD, KRT7, LMNA, LMNB1, LMNB2, RPTOR, HOXA1, PFKL, KMT2E/MLL5, MAPT/TAU, TET2, RBL2, RET, NOD2 and HCFC1 (PubMed:19451179, PubMed:20200153, PubMed:21285374, PubMed:22923583, PubMed:23353889, PubMed:24474760, PubMed:26237509, PubMed:26369908, PubMed:26678539, PubMed:27527864, PubMed:30699359, PubMed:34074792, PubMed:34667079, PubMed:37541260, PubMed:37962578). Can regulate their cellular processes via cross-talk between glycosylation and phosphorylation or by affecting proteolytic processing (PubMed:21285374). Involved in insulin resistance in muscle and adipocyte cells via glycosylating insulin signaling components and inhibiting the 'Thr-308' phosphorylation of AKT1, enhancing IRS1 phosphorylation and attenuating insulin signaling (By similarity). Involved in glycolysis regulation by mediating glycosylation of 6-phosphofructokinase PFKL, inhibiting its activity (PubMed:22923583). Plays a key role in chromatin structure by mediating O-GlcNAcylation of 'Ser-112' of histone H2B: recruited to CpG-rich transcription start sites of active genes via its interaction with TET proteins (TET1, TET2 or TET3) (PubMed:22121020, PubMed:23353889). As part of the NSL complex indirectly involved in acetylation of nucleosomal histone H4 on several lysine residues (PubMed:20018852). O-GlcNAcylation of 'Ser-75' of EZH2 increases its stability, and facilitating the formation of H3K27me3 by the PRC2/EED-EZH2 complex (PubMed:24474760). Stabilizes KMT2E/MLL5 by mediating its glycosylation, thereby preventing KMT2E/MLL5 ubiquitination (PubMed:26678539). Regulates circadian oscillation of the clock genes and glucose homeostasis in the liver (By similarity). Stabilizes clock proteins BMAL1 and CLOCK through O-glycosylation, which prevents their ubiquitination and subsequent degradation (By similarity). Promotes the CLOCK-BMAL1-mediated transcription of genes in the negative loop of the circadian clock such as PER1/2 and CRY1/2. O-glycosylates HCFC1 and regulates its proteolytic processing and transcriptional activity (PubMed:21285374, PubMed:28302723, PubMed:28584052). Component of a THAP1/THAP3-HCFC1-OGT complex that is required for the regulation of the transcriptional activity of RRM1 (PubMed:20200153). Regulates mitochondrial motility in neurons by mediating glycosylation of TRAK1 (By similarity). Promotes autophagy by mediating O-glycosylation of ATG4B (PubMed:27527864). Acts as a regulator of mTORC1 signaling by mediating O-glycosylation of RPTOR and FNIP1: O-GlcNAcylation of RPTOR in response to glucose sufficiency promotes activation of the mTORC1 complex (PubMed:30699359, PubMed:37541260)\nThe mitochondrial isoform (mOGT) is cytotoxic and triggers apoptosis in several cell types including INS1, an insulinoma cell line\nHas N-acetylglucosaminyltransferase activity: glycosylates proteins, such as HNRNPU, NEUROD1, NUP62 and PDCD6IP (PubMed:31527085). Displays specific substrate selectivity compared to other isoforms (PubMed:31527085)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"KRABD2":{"coreEvidence":[{"partner":"TP53","hgnc":"HGNC:11998","core":true,"core_annotation":{"hgnc":"HGNC:11998","symbol_at_source":"TP53","accession":"P04637","function":"Histone modification write cofactor, TF","target":"histone","pmids":["23870121"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1691,"hub_weight":0.16946718543287687,"quality":0.65,"programmes":["pubmed:32807901"],"pmids":["32807901"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Nucleus, PML body; Endoplasmic reticulum; Mitochondrion matrix; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Multifunctional transcription factor that induces cell cycle arrest, DNA repair or apoptosis upon binding to its target DNA sequence (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:35618207, PubMed:36634798, PubMed:38653238, PubMed:9840937). Acts as a tumor suppressor in many tumor types; induces growth arrest or apoptosis depending on the physiological circumstances and cell type (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17189187, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:38653238, PubMed:9840937). Negatively regulates cell division by controlling expression of a set of genes required for this process (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:9840937). One of the activated genes is an inhibitor of cyclin-dependent kinases. Apoptosis induction seems to be mediated either by stimulation of BAX and FAS antigen expression, or by repression of Bcl-2 expression (PubMed:12524540, PubMed:17189187). Its pro-apoptotic activity is activated via its interaction with PPP1R13B/ASPP1 or TP53BP2/ASPP2 (PubMed:12524540). However, this activity is inhibited when the interaction with PPP1R13B/ASPP1 or TP53BP2/ASPP2 is displaced by PPP1R13L/iASPP (PubMed:12524540). In cooperation with mitochondrial PPIF is involved in activating oxidative stress-induced necrosis; the function is largely independent of transcription. Induces the transcription of long intergenic non-coding RNA p21 (lincRNA-p21) and lincRNA-Mkln1. LincRNA-p21 participates in TP53-dependent transcriptional repression leading to apoptosis and seems to have an effect on cell-cycle regulation. Implicated in Notch signaling cross-over. Prevents CDK7 kinase activity when associated to CAK complex in response to DNA damage, thus stopping cell cycle progression. Isoform 2 enhances the transactivation activity of isoform 1 from some but not all TP53-inducible promoters. Isoform 4 suppresses transactivation activity and impairs growth suppression mediated by isoform 1. Isoform 7 inhibits isoform 1-mediated apoptosis. Regulates the circadian clock by repressing CLOCK-BMAL1-mediated transcriptional activation of PER2 (PubMed:24051492)","source":"project UniProt records20261017/18"},{"partner":"HDAC7","hgnc":"HGNC:14067","core":true,"core_annotation":{"hgnc":"HGNC:14067","symbol_at_source":"HDAC7","accession":"Q8WUI4","function":"Histone modification erase","target":"histone","pmids":["18285338"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":143,"hub_weight":0.5089865985592875,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Responsible for the deacetylation of lysine residues on the N-terminal part of the core histones (H2A, H2B, H3 and H4) (By similarity). Histone deacetylation gives a tag for epigenetic repression and plays an important role in transcriptional regulation, cell cycle progression and developmental events (By similarity). Histone deacetylases act via the formation of large multiprotein complexes (By similarity). Involved in muscle maturation by repressing transcription of myocyte enhancer factors such as MEF2A, MEF2B and MEF2C (By similarity). During muscle differentiation, it shuttles into the cytoplasm, allowing the expression of myocyte enhancer factors (By similarity). May be involved in Epstein-Barr virus (EBV) latency, possibly by repressing the viral BZLF1 gene (PubMed:12239305). Positively regulates the transcriptional repressor activity of FOXP3 (PubMed:17360565). Serves as a corepressor of RARA, causing its deacetylation and inhibition of RARE DNA element binding (PubMed:28167758). In association with RARA, plays a role in the repression of microRNA-10a and thereby in the inflammatory response (PubMed:28167758). Also acetylates non-histone proteins, such as ALKBH5 (PubMed:37369679)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"TSLIG3C":{"coreEvidence":[{"partner":"DR1","hgnc":"HGNC:3017","core":true,"core_annotation":{"hgnc":"HGNC:3017","symbol_at_source":"DR1","accession":"Q01658","function":"Histone chaperone","target":"histone","pmids":["18838386"],"complexes":"ATAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":103,"hub_weight":0.5716619504750294,"quality":0.75,"programmes":["pubmed:32814053"],"pmids":["32814053"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"The association of the DR1/DRAP1 heterodimer with TBP results in a functional repression of both activated and basal transcription of class II genes. This interaction precludes the formation of a transcription-competent complex by inhibiting the association of TFIIA and/or TFIIB with TBP. Can bind to DNA on its own. Component of the ATAC complex, a complex with histone acetyltransferase activity on histones H3 and H4","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"KCTD14":{"coreEvidence":[{"partner":"CHUK","hgnc":"HGNC:1974","core":true,"core_annotation":{"hgnc":"HGNC:1974","symbol_at_source":"CHUK","accession":"O15111","function":"Histone modification write","target":"histone","pmids":["17434128"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":158,"hub_weight":0.4902903378454601,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","dataset_cell:HCT116"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine kinase that plays an essential role in the NF-kappa-B signaling pathway which is activated by multiple stimuli such as inflammatory cytokines, bacterial or viral products, DNA damages or other cellular stresses (PubMed:18626576, PubMed:9244310, PubMed:9252186, PubMed:9346484). Acts as a part of the canonical IKK complex in the conventional pathway of NF-kappa-B activation and phosphorylates inhibitors of NF-kappa-B on serine residues (PubMed:18626576, PubMed:35952808, PubMed:9244310, PubMed:9252186, PubMed:9346484). These modifications allow polyubiquitination of the inhibitors and subsequent degradation by the proteasome (PubMed:18626576, PubMed:9244310, PubMed:9252186, PubMed:9346484). In turn, free NF-kappa-B is translocated into the nucleus and activates the transcription of hundreds of genes involved in immune response, growth control, or protection against apoptosis (PubMed:18626576, PubMed:9244310, PubMed:9252186, PubMed:9346484). Negatively regulates the pathway by phosphorylating the scaffold protein TAXBP1 and thus promoting the assembly of the A20/TNFAIP3 ubiquitin-editing complex (composed of A20/TNFAIP3, TAX1BP1, and the E3 ligases ITCH and RNF11) (PubMed:21765415). Therefore, CHUK plays a key role in the negative feedback of NF-kappa-B canonical signaling to limit inflammatory gene activation. As part of the non-canonical pathway of NF-kappa-B activation, the MAP3K14-activated CHUK/IKKA homodimer phosphorylates NFKB2/p100 associated with RelB, inducing its proteolytic processing to NFKB2/p52 and the formation of NF-kappa-B RelB-p52 complexes (PubMed:20501937). In turn, these complexes regulate genes encoding molecules involved in B-cell survival and lymphoid organogenesis. Also participates in the negative feedback of the non-canonical NF-kappa-B signaling pathway by phosphorylating and destabilizing MAP3K14/NIK. Within the nucleus, phosphorylates CREBBP and consequently increases both its transcriptional and histone acetyltransferase activities (PubMed:17434128). Modulates chromatin accessibility at NF-kappa-B-responsive promoters by phosphorylating histones H3 at 'Ser-10' that are subsequently acetylated at 'Lys-14' by CREBBP (PubMed:12789342). Additionally, phosphorylates the CREBBP-interacting protein NCOA3. Also phosphorylates FOXO3 and may regulate this pro-apoptotic transcription factor (PubMed:15084260). Phosphorylates RIPK1 at 'Ser-25' which represses its kinase activity and consequently prevents TNF-mediated RIPK1-dependent cell death (By similarity). Phosphorylates AMBRA1 following mitophagy induction, promoting AMBRA1 interaction with ATG8 family proteins and its mitophagic activity (PubMed:30217973)","source":"project UniProt records20261017/18"},{"partner":"AURKB","hgnc":"HGNC:11390","core":true,"core_annotation":{"hgnc":"HGNC:11390","symbol_at_source":"AURKB","accession":"Q96GD4","function":"Histone modification write","target":"histone","pmids":["11856369"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":583,"hub_weight":0.28104971365967135,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus; Chromosome; Chromosome, centromere; Chromosome, centromere, kinetochore; Cytoplasm, cytoskeleton, spindle; Midbody","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine-protein kinase component of the chromosomal passenger complex (CPC), a complex that acts as a key regulator of mitosis (PubMed:11516652, PubMed:12925766, PubMed:14610074, PubMed:14722118, PubMed:29449677). The CPC complex has essential functions at the centromere in ensuring correct chromosome alignment and segregation and is required for chromatin-induced microtubule stabilization and spindle assembly (PubMed:11516652, PubMed:12925766, PubMed:14610074, PubMed:14722118, PubMed:26829474). Involved in the bipolar attachment of spindle microtubules to kinetochores and is a key regulator for the onset of cytokinesis during mitosis (PubMed:15249581). Required for central/midzone spindle assembly and cleavage furrow formation (PubMed:12458200, PubMed:12686604). Key component of the cytokinesis checkpoint, a process required to delay abscission to prevent both premature resolution of intercellular chromosome bridges and accumulation of DNA damage: phosphorylates CHMP4C, leading to retain abscission-competent VPS4 (VPS4A and/or VPS4B) at the midbody ring until abscission checkpoint signaling is terminated at late cytokinesis (PubMed:22422861, PubMed:24814515). AURKB phosphorylates the CPC complex subunits BIRC5/survivin, CDCA8/borealin and INCENP (PubMed:11516652, PubMed:12925766, PubMed:14610074). Phosphorylation of INCENP leads to increased AURKB activity (PubMed:11516652, PubMed:12925766, PubMed:14610074). Other known AURKB substrates involved in centromeric functions and mitosis are CENPA, DES/desmin, GPAF, KIF2C, NSUN2, RACGAP1, SEPTIN1, VIM/vimentin, HASPIN, and histones H1.4 and H3 (PubMed:11756469, PubMed:11784863, PubMed:11856369, PubMed:12689593, PubMed:14602875, PubMed:16103226, PubMed:21511733, PubMed:21658950). A positive feedback loop involving HASPIN and AURKB contributes to localization of CPC to centromeres (PubMed:21658950). Phosphorylation of VIM controls vimentin filament segregation in cytokinetic process, whereas histone H3 is phosphorylated at 'Ser-10' and 'Ser-28' during mitosis (H3S10ph and H3S28ph, respectively) (PubMed:11784863, PubMed:11856369). AURKB is also required for kinetochore localization of BUB1 and SGO1 (PubMed:15020684, PubMed:17617734). Phosphorylation of p53/TP53 negatively regulates its transcriptional activity (PubMed:20959462). Key regulator of active promoters in resting B- and T-lymphocytes: acts by mediating phosphorylation of H3S28ph at active promoters in resting B-cells, inhibiting RNF2/RING1B-mediated ubiquitination of histone H2A and enhancing binding and activity of the USP16 deubiquitinase at transcribed genes (By similarity). Acts as an inhibitor of CGAS during mitosis: catalyzes phosphorylation of the N-terminus of CGAS during the G2-M transition, blocking CGAS liquid phase separation and activation, and thereby preventing CGAS-induced autoimmunity (PubMed:33542149). Phosphorylates KRT5 during anaphase and telophase (By similarity). Phosphorylates ATXN10 which promotes phosphorylation of ATXN10 by PLK1 and may play a role in the regulation of cytokinesis and stimulating the proteasomal degradation of ATXN10 (PubMed:25666058)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"C8orf82":{"coreEvidence":[{"partner":"SFPQ","hgnc":"HGNC:10774","core":true,"core_annotation":{"hgnc":"HGNC:10774","symbol_at_source":"SFPQ","accession":"P23246","function":"Chromatin remodeling cofactor, RNA modification, TF","target":"DNA, RNA","pmids":["22783022","10858305","8449401"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":444,"hub_weight":0.31814238148788887,"quality":0.4,"programmes":["pubmed:32877691"],"pmids":["32877691"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus speckle; Nucleus matrix; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"DNA- and RNA binding protein, involved in several nuclear processes. Essential pre-mRNA splicing factor required early in spliceosome formation and for splicing catalytic step II, probably as a heteromer with NONO. Binds to pre-mRNA in spliceosome C complex, and specifically binds to intronic polypyrimidine tracts. Involved in regulation of signal-induced alternative splicing. During splicing of PTPRC/CD45, a phosphorylated form is sequestered by THRAP3 from the pre-mRNA in resting T-cells; T-cell activation and subsequent reduced phosphorylation is proposed to lead to release from THRAP3 allowing binding to pre-mRNA splicing regulatotry elements which represses exon inclusion. Interacts with U5 snRNA, probably by binding to a purine-rich sequence located on the 3' side of U5 snRNA stem 1b. May be involved in a pre-mRNA coupled splicing and polyadenylation process as component of a snRNP-free complex with SNRPA/U1A. The SFPQ-NONO heteromer associated with MATR3 may play a role in nuclear retention of defective RNAs. SFPQ may be involved in homologous DNA pairing; in vitro, promotes the invasion of ssDNA between a duplex DNA and produces a D-loop formation. The SFPQ-NONO heteromer may be involved in DNA unwinding by modulating the function of topoisomerase I/TOP1; in vitro, stimulates dissociation of TOP1 from DNA after cleavage and enhances its jumping between separate DNA helices. The SFPQ-NONO heteromer binds DNA (PubMed:25765647). The SFPQ-NONO heteromer may be involved in DNA non-homologous end joining (NHEJ) required for double-strand break repair and V(D)J recombination and may stabilize paired DNA ends; in vitro, the complex strongly stimulates DNA end joining, binds directly to the DNA substrates and cooperates with the Ku70/G22P1-Ku80/XRCC5 (Ku) dimer to establish a functional preligation complex. SFPQ is involved in transcriptional regulation. Functions as a transcriptional activator (PubMed:25765647). Transcriptional repression is mediated by an interaction of SFPQ with SIN3A and subsequent recruitment of histone deacetylases (HDACs). The SFPQ-NONO-NR5A1 complex binds to the CYP17 promoter and regulates basal and cAMP-dependent transcriptional activity. SFPQ isoform Long binds to the DNA binding domains (DBD) of nuclear hormone receptors, like RXRA and probably THRA, and acts as a transcriptional corepressor in absence of hormone ligands. Binds the DNA sequence 5'-CTGAGTC-3' in the insulin-like growth factor response element (IGFRE) and inhibits IGF1-stimulated transcriptional activity. Regulates the circadian clock by repressing the transcriptional activator activity of the CLOCK-BMAL1 heterodimer. Required for the transcriptional repression of circadian target genes, such as PER1, mediated by the large PER complex through histone deacetylation (By similarity). Required for the assembly of nuclear speckles (PubMed:25765647). Plays a role in the regulation of DNA virus-mediated innate immune response by assembling into the HDP-RNP complex, a complex that serves as a platform for IRF3 phosphorylation and subsequent innate immune response activation through the cGAS-STING pathway (PubMed:28712728)","source":"project UniProt records20261017/18"},{"partner":"SPOP","hgnc":"HGNC:11254","core":true,"core_annotation":{"hgnc":"HGNC:11254","symbol_at_source":"SPOP","accession":"O43791","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":367,"hub_weight":0.34627168053222185,"quality":0.65,"programmes":["pubmed:36604567"],"pmids":["36604567"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Nucleus speckle; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex that mediates the ubiquitination of target proteins, leading most often to their proteasomal degradation. In complex with CUL3, involved in ubiquitination and proteasomal degradation of BRMS1, DAXX, PDX1/IPF1, GLI2 and GLI3. In complex with CUL3, involved in ubiquitination of MACROH2A1 and BMI1; this does not lead to their proteasomal degradation. Inhibits transcriptional activation of PDX1/IPF1 targets, such as insulin, by promoting PDX1/IPF1 degradation. The cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOP has higher ubiquitin ligase activity than the complex that contains the heterodimer formed by SPOP and SPOPL. Involved in the regulation of bromodomain and extra-terminal motif (BET) proteins BRD2, BRD3, BRD4 stability (PubMed:32109420). Plays an essential role for proper translation, but not for their degradation, of critical DNA replication licensing factors CDT1 and CDC6, thereby participating in DNA synthesis and cell proliferation (PubMed:36791496). Regulates interferon regulatory factor 1/IRF1 proteasomal turnover by targeting S/T-rich degrons in IRF1 (PubMed:37622993). Facilitates the lysosome-dependent degradation of enterovirus EV71 protease 2A by inducing its 'Lys-48'-linked polyubiquitination, which ultimately restricts EV71 replication (PubMed:37796126). Acts as an antiviral factor also against hepatitis B virus/HBV by promoting ubiquitination and subsequent degradation of HNF1A (PubMed:38018242). In turn, inhibits HBV transcription and replication by preventing HNF1A stimulating activity of HBV preS1 promoter and enhancer II (PubMed:38018242). Involved in ubiquitination of BRDT and promotes its degradation, thereby regulates histone removal in early condensing spermatids prior to histone-to-protamine exchange (By similarity)","source":"project UniProt records20261017/18"},{"partner":"TDRD3","hgnc":"HGNC:20612","core":true,"core_annotation":{"hgnc":"HGNC:20612","symbol_at_source":"TDRD3","accession":"Q9H7E2","function":"Histone modification read","target":"histone","pmids":["21172665"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":158,"hub_weight":0.4902903378454601,"quality":0.4,"programmes":["pubmed:32877691"],"pmids":["32877691"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Scaffolding protein that specifically recognizes and binds dimethylarginine-containing proteins (PubMed:15955813). Plays a role in the regulation of translation of target mRNAs by binding Arg/Gly-rich motifs (GAR) in dimethylarginine-containing proteins. In nucleus, acts as a coactivator: recognizes and binds asymmetric dimethylation on the core histone tails associated with transcriptional activation (H3R17me2a and H4R3me2a) and recruits proteins at these arginine-methylated loci (PubMed:21172665). In cytoplasm, acts as an antiviral factor that participates in the assembly of stress granules together with G3BP1 (PubMed:35085371)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"EFCC1":{"coreEvidence":[{"partner":"CUL1","hgnc":"HGNC:2551","core":true,"core_annotation":{"hgnc":"HGNC:2551","symbol_at_source":"CUL1","accession":"Q13616","function":"Chromatin remodeling cofactor","target":"histone","pmids":["9663463"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":690,"hub_weight":0.25993762245501817,"quality":0.65,"programmes":["pubmed:21145461"],"pmids":["21145461"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Core component of multiple cullin-RING-based SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complexes, which mediate the ubiquitination of proteins involved in cell cycle progression, signal transduction and transcription. SCF complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:22017875, PubMed:22017877, PubMed:27565346). In the SCF complex, serves as a rigid scaffold that organizes the SKP1-F-box protein and RBX1 subunits. May contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme (PubMed:38326650). The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and exchange of the substrate recognition component is mediated by TIP120A/CAND1 (PubMed:12609982, PubMed:38326650). The functional specificity of the SCF complex depends on the F-box protein as substrate recognition component (PubMed:38326650). SCF(BTRC) and SCF(FBXW11) direct ubiquitination of CTNNB1 and participate in Wnt signaling. SCF(FBXW11) directs ubiquitination of phosphorylated NFKBIA. SCF(BTRC) directs ubiquitination of NFKBIB, NFKBIE, ATF4, SMAD3, SMAD4, CDC25A, FBXO5 and probably NFKB2. SCF(BTRC) and/or SCF(FBXW11) direct ubiquitination of CEP68 (PubMed:25503564, PubMed:25704143). SCF(SKP2) directs ubiquitination of phosphorylated CDKN1B/p27kip and is involved in regulation of G1/S transition. SCF(SKP2) directs ubiquitination of ORC1, CDT1, RBL2, ELF4, CDKN1A, RAG2, FOXO1A, and probably MYC and TAL1. SCF(FBXW7) directs ubiquitination of CCNE1, NOTCH1 released notch intracellular domain (NICD), and probably PSEN1. SCF(FBXW2) directs ubiquitination of GCM1. SCF(FBXO32) directs ubiquitination of MYOD1. SCF(FBXO7) directs ubiquitination of BIRC2 and DLGAP5. SCF(FBXO33) directs ubiquitination of YBX1. SCF(FBXO1) directs ubiquitination of BCL6 and DTL but does not seem to direct ubiquitination of TP53. SCF(BTRC) mediates the ubiquitination of NFKBIA at 'Lys-21' and 'Lys-22'; the degradation frees the associated NFKB1-RELA dimer to translocate into the nucleus and to activate transcription. SCF(CCNF) directs ubiquitination of CCP110. SCF(FBXL3) and SCF(FBXL21) direct ubiquitination of CRY1 and CRY2. SCF(FBXO9) directs ubiquitination of TTI1 and TELO2. SCF(FBXO10) directs ubiquitination of BCL2. Neddylated CUL1-RBX1 ubiquitinates p53/TP53 recruited by Cul7-RING(FBXW8) complex (PubMed:35982156). SCF(BTRC) directs 'Lys-48'-linked ubiquitination of UBR2 in the T-cell receptor signaling pathway (PubMed:38225265). The SCF(FBXO31) protein ligase complex specifically mediates the ubiquitination of proteins amidated at their C-terminus in response to oxidative stress (PubMed:39880951)","source":"project UniProt records20261017/18"},{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"WDR17":{"coreEvidence":[{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"},{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]}};
